    for (const rel of ["./templates", "../templates"]) {
      const dir = fileURLToPath(new URL(rel, import.meta.url));
      if (existsSync(`${dir}/chart.md`)) return dir;
    }
    throw new Error("workflow plugin templates directory not found");
  })();
